// ============================================================
// UNDERSTAND pom.xml
// ============================================================
// pom.xml = Project Object Model.
// It controls things such as:
// - project information
// - Java version
// - dependencies
// - plugins
// - build configuration
// - packaging
// - Maven behavior
// Important sections to recognize:
// <groupId>
// <artifactId>
// <version>
// <properties>
// <dependencies>
// <build>
// <plugins>
// A dependency normally looks like:
// <dependency>
//     <groupId>...</groupId>
//     <artifactId>...</artifactId>
//     <version>...</version>
// </dependency>
// Do not randomly change pom.xml.
// First identify what the project actually requires.
// ============================================================
// MAVEN — CHECK INSTALLATION
// ============================================================
// Check Maven:
// mvn -version
// If Maven works, you should see Apache Maven information and the Java version Maven is using.
// If you get:
// 'mvn' is not recognized as an internal or external command
// the usual causes are:
// 1. Maven is not installed.
// 2. Maven's bin directory is not in PATH.
// ============================================================
// CONFIGURE MAVEN PATH
// ============================================================
// If Maven is installed at:
// D:\DevTools\apache-maven
// then its bin directory is:
// D:\DevTools\apache-maven\bin
// Add that directory to Windows PATH.
// Windows steps:
// Search:
// Environment Variables
// Open:
// Edit the system environment variables
// Then:
// Environment Variables
// Under System variables:
// Path
//   -> Edit
//   -> New
// Add the Maven bin path, for example:
// D:\DevTools\apache-maven\bin
// Close/reopen Command Prompt or PowerShell.
// Test:
// mvn -version
// ============================================================
// MAVEN DEPENDENCY PROBLEM
// ============================================================
// If Eclipse reports that dependencies cannot be resolved:
// 1. Open pom.xml.
// 2. Inspect the <dependencies> section.
// 3. Check groupId.
// 4. Check artifactId.
// 5. Check version.
// 6. Check whether the dependency is available from Maven repositories.
// 7. Check internet connectivity.
// 8. Update the Maven project in Eclipse.
// You can force Maven to check updated dependencies:
// mvn clean install -U
// Maven normally stores downloaded dependencies under:
// C:\Users\<username>\.m2\repository
// If a dependency download is corrupted, the problematic dependency's folder can be removed and Maven can download it again.
// ============================================================
// FIRST BUILD
// ============================================================
// From the HMS root folder:
// mvn clean install
// Understand:
// mvn
// = run Maven
// clean
// = remove previous build output
// install
// = compile
//   test
//   package
//   install the artifact into the local Maven repository
// Basic Maven lifecycle commands:
// mvn clean
// mvn compile
// mvn test
// mvn package
// mvn install
// mvn clean install
// ============================================================
// IF COMPILATION FAILS
// ============================================================
// Do not immediately change source code.
// 1. Read the terminal output.
// 2. Find ERROR messages.
// 3. Identify the first meaningful error.
// 4. Look for messages such as:
//    - cannot find symbol
//    - package ... does not exist
//    - incompatible types
//    - source option ...
//    - target option ...
// 5. Check dependencies and Java compatibility.
// 6. Rerun Maven after fixing the actual cause.
// More detailed Maven output:
// mvn clean install -e
// -e = detailed error information
// For very detailed debugging:
// mvn clean install -X
// -X = debug-level Maven output
// ============================================================
// JAVA VERSION COMPATIBILITY
// ============================================================
// If the HMS project was developed using a different Java version:
// Check:
// java -version
// javac -version
// mvn -version
// IMPORTANT:
// mvn -version shows which Java version Maven is actually using.
// Also inspect pom.xml for Java configuration, for example:
// <maven.compiler.source>...</maven.compiler.source>
// <maven.compiler.target>...</maven.compiler.target>
// or:
// <java.version>...</java.version>
// The project's required Java version and your installed JDK must be compatible.
// Check JAVA_HOME.
// PowerShell:
// echo $env:JAVA_HOME
// CMD:
// echo %JAVA_HOME%
// Do not blindly change the Java version just to remove an error. Match the project requirement.
// ============================================================
// SKIPPING TESTS TEMPORARILY
// ============================================================
// If compilation succeeds but tests fail because an external service is unavailable, and the immediate requirement is to generate the application package:
// mvn clean install -DskipTests
// -DskipTests
// = do not run tests
// Another option:
// mvn clean install -Dmaven.test.skip=true
// Difference to remember:
// -DskipTests
// = skips running tests
// -Dmaven.test.skip=true
// = skips test compilation and execution
// RISK:
// Skipping tests can produce a package even though the application has not been fully tested. Use this temporarily, not as a permanent solution.
// ============================================================
// MAVEN DEPENDENCY CONFLICT
// ============================================================
// If two libraries depend on different versions of the same library:
// Example:
// Library A -> X version 1
// Library B -> X version 2
// Use:
// mvn dependency:tree
// This shows which dependencies bring which versions.
// Then identify the unwanted/transitive dependency.
// A dependency can be excluded using:
// <dependency>
//     <groupId>...</groupId>
//     <artifactId>...</artifactId>
//     <exclusions>
//         <exclusion>
//             <groupId>...</groupId>
//             <artifactId>...</artifactId>
//         </exclusion>
//     </exclusions>
// </dependency>
// Then explicitly add the desired compatible version if required.
// ============================================================
// pom.xml CHANGE BROKE THE APPLICATION
// ============================================================
// If the application worked before a pom.xml change:
// 1. Check what dependency/configuration changed.
// 2. Use:
// git diff
// 3. Use:
// mvn dependency:tree
// 4. Look for dependency/version conflicts.
// 5. Run:
// mvn clean install
// 6. If necessary, revert the dependency change.
// ============================================================
// BUILD SUCCESS BUT BROWSER DOES NOT LOAD
// ============================================================
// IMPORTANT:
// BUILD SUCCESS != application server is running.
// Check:
// 1. Did the application/server actually start?
// 2. Are there startup errors?
// 3. Is the correct port being used?
// 4. Is another process already using the port?
// 5. Is the correct URL/context path being used?
// For port 8080 on Windows:
// netstat -ano | findstr :8080
// If the application uses port 8080, try:
// http://localhost:8080
// The actual application may use a context path such as:
// http://localhost:8080/HMS
// Do not assume the exact context path without checking the project/server configuration.
// Check logs for:
// ERROR
// Exception
// Failed
// Port already in use
// ============================================================
// MAVEN BUILD PLUGIN PROBLEM
// ============================================================
// If Maven reports that a required build plugin cannot be found/executed:
// Before changing source code inspect pom.xml, especially:
// <build>
// <plugins>
// <plugin>
// Check:
// <groupId>
// <artifactId>
// <version>
// and plugin configuration.
// ============================================================
// MAVEN MASTER COMMAND LIST
// ============================================================
// mvn -version
// mvn clean
// mvn compile
// mvn test
// mvn package
// mvn install
// mvn clean install
// mvn clean install -DskipTests
// mvn dependency:tree
// mvn clean install -U
// mvn clean install -e
// mvn clean install -X
// ============================================================
// PART 2 — GIT / GITHUB
// ============================================================
// The Git section uses the HMS/register.jsp hospital appointment scenario.
// ============================================================
// GIT — NORMAL FOLDER TO REPOSITORY
// ============================================================
// If the HMS folder is not under Git version control:
// cd HMS
// Initialize:
// git init
// Check:
// git status
// Stage everything:
// git add .
// Check staging:
// git status
// Commit:
// git commit -m "Initial commit"
// Remember:
// Working Directory
//       |
//       | git add
//       v
// Staging Area
//       |
//       | git commit
//       v
// Repository
// ============================================================
// FEATURE: MOBILE NUMBER + PASSWORD VALIDATION
// ============================================================
// Professional Git workflow:
// 1. Check status.
// 2. Create a feature branch.
// 3. Modify register.jsp.
// 4. Test the changes.
// 5. Inspect changes.
// 6. Stage.
// 7. Commit.
// 8. Push.
// Create feature branch:
// git switch -c registration-enhancement
// Older Git alternative:
// git checkout -b registration-enhancement
// Check branches:
// git branch
// Modify:
// register.jsp
// Save changes.
// Check:
// git status

// Inspect:

// git diff

// Stage:

// git add .

// Commit:

// git commit -m "Improve patient registration form"

// ============================================================
// GIT DIFF
// ============================================================

// To inspect exactly what changed before committing:

// git diff

// It shows changes between the working directory and staging area.

// Typical output uses:

// - = removed/old line
// + = added/new line

// ============================================================
// STAGING MODIFIED + NEW FILES
// ============================================================

// If register.jsp is modified and style.css is new:

// git add register.jsp
// git add style.css

// Or:

// git add .

// Then:

// git status

// The files should appear under:

// Changes to be committed

// Commit:

// git commit -m "Improve patient registration form"

// ============================================================
// UNDO A BAD COMMIT WHILE PRESERVING HISTORY
// ============================================================

// Use:

// git revert <commit-id>

// Example:

// git revert abc1234

// Why?

// git revert creates a NEW commit that reverses the effect of the old commit.

// History remains intact.

// Concept:

// old history
//     |
// bad commit
//     |
// revert commit

// Do not confuse this with git reset.

// For the requirement "undo the commit while preserving existing Git history", use git revert.

// ============================================================
// UNSTAGE A FILE WITHOUT DELETING IT
// ============================================================

// If a configuration file was accidentally staged:

// git restore --staged config.properties

// This removes it from the staging area but keeps the file in the working directory.

// Older Git alternative:

// git reset HEAD config.properties

// ============================================================
// URGENT WORK WHILE CURRENT CHANGES ARE UNFINISHED
// ============================================================

// Scenario:

// You are halfway through register.jsp work, but your team lead asks you to fix an urgent appointment issue on another branch.

// Save unfinished work temporarily:

// git stash

// Switch branch:

// git switch appointment-fix

// Fix the urgent issue.

// Stage:

// git add .

// Commit:

// git commit -m "Fix appointment booking issue"

// Return to original branch:

// git switch registration-enhancement

// Restore unfinished work:

// git stash pop

// Memory flow:

// working on A
//     |
// urgent work B
//     |
// git stash
//     |
// switch to B
//     |
// fix B
//     |
// commit
//     |
// switch to A
//     |
// git stash pop

// ============================================================
// FEATURE BRANCH + UPDATED MAIN BRANCH
// ============================================================

// If main has received new commits and the team wants a clean project history:

// Switch to main:

// git switch main

// Get latest main:

// git pull

// Return to feature branch:

// git switch registration-enhancement

// Rebase:

// git rebase main

// If there is a conflict:

// 1. Open the conflicting file.
// 2. Resolve the conflict.
// 3. Stage it:

// git add <file>

// 4. Continue:

// git rebase --continue

// If you need to cancel the rebase:

// git rebase --abort

// Conflict markers may look like:

// <<<<<<< HEAD
// main version
// =======
// your version
// >>>>>>> ...

// Edit to the correct final content.

// ============================================================
// RECOVER A LOST COMMIT
// ============================================================

// Use:

// git reflog

// git reflog shows previous HEAD positions and is useful for recovering commits that are no longer easy to find.

// After finding the commit hash, inspect it:

// git show <commit-id>

// You can recover it by creating a branch:

// git switch -c recovered-work <commit-id>

// ============================================================
// PUSH HMS TO GITHUB
// ============================================================

// Create a GitHub repository first.

// Then inside the project:

// git remote add origin <URL>

// Example form:

// git remote add origin https://github.com/YOUR_USERNAME/HMS.git

// Check:

// git remote -v

// If the branch should be main:

// git branch -M main

// Push:

// git push -u origin main

// If pushing a feature branch:

// git push -u origin registration-enhancement

// ============================================================
// GIT MASTER COMMAND LIST
// ============================================================

// git init
// git status
// git add .
// git add <file>
// git commit -m "message"
// git diff
// git switch -c feature
// git switch main
// git stash
// git stash pop
// git revert <commit>
// git restore --staged <file>
// git reflog
// git show <commit>
// git remote add origin <URL>
// git remote -v
// git push -u origin main
// git pull
// git rebase main
// git rebase --continue
// git rebase --abort

// ============================================================
// PART 3 — DOCKER
// ============================================================

// The practical Docker task is:

// 1. Create a Dockerfile.
// 2. Build an image named HMS.
// 3. Run the image in a container.
// 4. Expose port 8080.
// 5. Check http://localhost:8080.
// 6. Tag the image for DockerHub.
// 7. Push it.

// ============================================================
// DOCKER — CHECK INSTALLATION
// ============================================================

// Check version:

// docker --version

// Check Docker engine:

// docker info

// Docker Desktop should be running.

// ============================================================
// BUILD HMS BEFORE DOCKER
// ============================================================

// Go to the HMS root folder:

// cd D:\HMS-Lab\HMS

// Build/package the application:

// mvn clean package

// If tests are the only blocker and the task permits temporary test skipping:

// mvn clean package -DskipTests

// ============================================================
// FIND THE GENERATED APPLICATION PACKAGE
// ============================================================

// Look inside:

// target

// Command:

// dir target

// Look for:

// *.jar

// or:

// *.war

// IMPORTANT:
// Do not blindly assume the generated file is named app.jar.
// Use the actual filename generated by this HMS project.

// ============================================================
// CREATE THE DOCKERFILE
// ============================================================

// Inside the HMS root directory, create a file named exactly:

// Dockerfile

// NOT:

// Dockerfile.txt

// A typical Java application Dockerfile structure is:

// FROM eclipse-temurin:17-jre

// WORKDIR /app

// COPY target/<actual-file>.jar app.jar

// EXPOSE 8080

// ENTRYPOINT ["java", "-jar", "app.jar"]

// IMPORTANT:
// The Java version must match the actual HMS project's requirements. Do not blindly use 17 if the project requires another version.

// ============================================================
// UNDERSTAND EVERY DOCKERFILE LINE
// ============================================================

// FROM eclipse-temurin:17-jre

// Means:
// Start from a Java runtime base image.

// WORKDIR /app

// Means:
// Set /app as the working directory inside the container.

// COPY target/<actual-file>.jar app.jar

// Means:
// Copy the generated application package from the build context into the container as app.jar.

// EXPOSE 8080

// Means:
// Document that the application uses container port 8080.

// ENTRYPOINT ["java", "-jar", "app.jar"]

// Means:
// When the container starts, run:

// java -jar app.jar

// ============================================================
// BUILD THE DOCKER IMAGE
// ============================================================

// The assignment asks for an image named HMS.

// Run:

// docker build -t HMS .

// Meaning:

// docker build
// = create a Docker image

// -t HMS
// = give the image the name HMS

// .
// = use the current directory as the build context

// ============================================================
// CHECK THE IMAGE
// ============================================================

// docker images

// Look for:

// HMS

// ============================================================
// RUN THE CONTAINER
// ============================================================

// Run:

// docker run -d -p 8080:8080 --name hms-container HMS

// Meaning:

// -d
// = detached/background mode

// -p 8080:8080
// = map host port 8080 to container port 8080

// --name hms-container
// = give the container a name

// HMS
// = image to run

// ============================================================
// UNDERSTAND 8080:8080
// ============================================================

// Docker port format:

// HOST PORT : CONTAINER PORT

// So:

// 8080:8080

// means:

// your computer port 8080
//         |
//         v
// container port 8080

// Therefore:

// http://localhost:8080

// can reach the application listening on container port 8080, assuming the application is actually configured/running on that port.

// ============================================================
// CHECK THE CONTAINER
// ============================================================

// Running containers:

// docker ps

// All containers:

// docker ps -a

// Look for:

// hms-container

// and a port mapping similar to:

// 0.0.0.0:8080->8080/tcp

// ============================================================
// OPEN THE APPLICATION
// ============================================================

// Browser:

// http://localhost:8080

// If the application uses a context path, the actual URL may be something like:

// http://localhost:8080/HMS

// Check the project/server configuration rather than guessing.

// ============================================================
// IF THE CONTAINER DOES NOT WORK
// ============================================================

// First:

// docker ps

// If it is not running:

// docker ps -a

// Then:

// docker logs hms-container

// Look for:

// ERROR
// Exception
// Failed
// Port
// Database
// startup problems

// If the container immediately exits, inspect the logs.

// Common causes include:

// - wrong JAR filename
// - wrong Java version
// - application startup failure
// - missing configuration
// - database unavailable
// - incorrect command
// - incorrect port

// ============================================================
// DOCKER BUILD FAILURE TROUBLESHOOTING
// ============================================================

// If:

// docker build -t HMS .

// fails:

// 1. Read the build output carefully.
// 2. Identify the first meaningful error.
// 3. Open Dockerfile.
// 4. Check FROM.
// 5. Check COPY paths.
// 6. Check actual generated JAR/WAR filename.
// 7. Check RUN commands if present.
// 8. Check EXPOSE.
// 9. Check ENTRYPOINT.
// 10. Correct the problem.
// 11. Build again.

// Example:

// COPY failed
// = usually wrong path/file name or missing file

// no matching manifest
// = image/tag/platform issue

// file not found
// = incorrect path/name or missing build artifact

// ============================================================
// DOCKER PORT ACCESS
// ============================================================

// If the application runs on port 8080 inside the container but localhost:8080 cannot access it, map the host port to the container port.

// Example:

// docker run -p 8080:8080 HMS

// Then:

// http://localhost:8080

// Flow:

// Browser
//   |
// localhost:8080
//   |
// Docker host port 8080
//   |
// container port 8080
//   |
// HMS application

// ============================================================
// DOCKER CONTAINER MANAGEMENT
// ============================================================

// Stop:

// docker stop hms-container

// Start an existing container:

// docker start hms-container

// Remove:

// docker rm hms-container

// If it is still running:

// docker rm -f hms-container

// Logs:

// docker logs hms-container

// ============================================================
// DOCKERHUB LOGIN
// ============================================================

// Log in:

// docker login

// Enter DockerHub credentials when prompted.

// ============================================================
// TAG HMS IMAGE
// ============================================================

// Suppose your DockerHub username is:

// YOUR_USERNAME

// Tag:

// docker tag HMS YOUR_USERNAME/HMS:latest

// General format:

// docker tag LOCAL_IMAGE USERNAME/REPOSITORY:TAG

// Check:

// docker images

// You should see the local HMS image and the DockerHub-tagged image.

// ============================================================
// PUSH TO DOCKERHUB
// ============================================================

// Push:

// docker push YOUR_USERNAME/HMS:latest

// Then verify the repository and tag on DockerHub.

// ============================================================
// COMPLETE DOCKER FLOW
// ============================================================

// Maven package
//       |
//       v
// target/*.jar or *.war
//       |
//       v
// Create Dockerfile
//       |
//       v
// docker build -t HMS .
//       |
//       v
// Docker image
//       |
//       v
// docker run -d -p 8080:8080 --name hms-container HMS
//       |
//       v
// docker ps
//       |
//       v
// http://localhost:8080
//       |
//       v
// docker login
//       |
//       v
// docker tag HMS username/HMS:latest
//       |
//       v
// docker push username/HMS:latest

